class VaultItem { final String id,name,path,type,method; final int bytes; final DateTime created; VaultItem({required this.id,required this.name,required this.path,required this.type,required this.method,required this.bytes,required this.created}); Map<String,dynamic> toJson()=>{'id':id,'name':name,'path':path,'type':type,'method':method,'bytes':bytes,'created':created.toIso8601String()}; factory VaultItem.fromJson(Map<String,dynamic> j)=>VaultItem(id:j['id'],name:j['name'],path:j['path'],type:j['type'],method:j['method'],bytes:j['bytes'],created:DateTime.parse(j['created'])); }
